CREATE TABLE IF NOT EXISTS cashiers (cashier_id VARCHAR(64) PRIMARY KEY, password_hash VARCHAR(255) NOT NULL, display_name VARCHAR(100) NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS members (member_id VARCHAR(64) PRIMARY KEY, name VARCHAR(100) NOT NULL, phone VARCHAR(32), address VARCHAR(255), gender VARCHAR(32), birth_date DATE, is_active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS tax_categories (tax_category_id BIGINT PRIMARY KEY AUTO_INCREMENT, category_code VARCHAR(32) UNIQUE NOT NULL, category_name VARCHAR(100) NOT NULL);
CREATE TABLE IF NOT EXISTS tax_rates (tax_rate_id BIGINT PRIMARY KEY AUTO_INCREMENT, tax_category_id BIGINT NOT NULL, tax_rate DECIMAL(5,2) NOT NULL, applicable_from DATETIME NOT NULL, applicable_to DATETIME NULL, FOREIGN KEY(tax_category_id) REFERENCES tax_categories(tax_category_id), INDEX idx_tax_rate_period (tax_category_id, applicable_from, applicable_to));
CREATE TABLE IF NOT EXISTS products (product_id BIGINT PRIMARY KEY AUTO_INCREMENT, product_code VARCHAR(64) UNIQUE NOT NULL, product_name VARCHAR(255) NOT NULL, current_unit_price DECIMAL(12,2) NOT NULL, image_url VARCHAR(2048) NULL, tax_category_id BIGINT NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE, FOREIGN KEY(tax_category_id) REFERENCES tax_categories(tax_category_id));
CREATE TABLE IF NOT EXISTS product_price_histories (price_history_id BIGINT PRIMARY KEY AUTO_INCREMENT, product_id BIGINT NOT NULL, unit_price DECIMAL(12,2) NOT NULL, applicable_from DATETIME NOT NULL, FOREIGN KEY(product_id) REFERENCES products(product_id));
CREATE TABLE IF NOT EXISTS promotion_rules (rule_id BIGINT PRIMARY KEY AUTO_INCREMENT, product_id BIGINT NOT NULL, applicable_from DATETIME NOT NULL, applicable_to DATETIME NULL, discount_type ENUM('RATE','AMOUNT') NOT NULL, discount_value DECIMAL(12,2) NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE, FOREIGN KEY(product_id) REFERENCES products(product_id), INDEX idx_promotion_period (product_id, applicable_from, applicable_to));
CREATE TABLE IF NOT EXISTS transactions (transaction_id BIGINT PRIMARY KEY AUTO_INCREMENT, request_id CHAR(36) NOT NULL UNIQUE, request_hash CHAR(64) NOT NULL, purchased_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, member_id VARCHAR(64) NULL, cashier_id VARCHAR(64) NOT NULL, subtotal DECIMAL(12,2) NOT NULL, tax_total DECIMAL(12,2) NOT NULL, grand_total DECIMAL(12,2) NOT NULL, FOREIGN KEY(member_id) REFERENCES members(member_id), FOREIGN KEY(cashier_id) REFERENCES cashiers(cashier_id));
CREATE TABLE IF NOT EXISTS transaction_details (detail_id BIGINT PRIMARY KEY AUTO_INCREMENT, transaction_id BIGINT NOT NULL, product_id BIGINT NOT NULL, quantity INT NOT NULL, sold_unit_price DECIMAL(12,2) NOT NULL, discount_amount DECIMAL(12,2) NOT NULL, applied_tax_rate DECIMAL(5,2) NOT NULL, tax_amount DECIMAL(12,2) NOT NULL, line_total DECIMAL(12,2) NOT NULL, FOREIGN KEY(transaction_id) REFERENCES transactions(transaction_id), FOREIGN KEY(product_id) REFERENCES products(product_id));
